BEGIN READ ONLY;
SET LOCAL statement_timeout = '8s';
SELECT jsonb_build_object('check','candidate-T4-004-option-1','result',COALESCE(jsonb_agg(candidate_row),'[]'::jsonb)) FROM (SELECT t.product_category_name_english, ROUND(SUM(oi.price),2) AS sales FROM order_items oi JOIN products p ON p.product_id=oi.product_id LEFT JOIN product_category_translation t ON t.product_category_name=p.product_category_name WHERE p.product_category_name IS NOT NULL GROUP BY p.product_category_name,t.product_category_name_english ORDER BY sales DESC,p.product_category_name LIMIT 1) candidate_row;
SELECT jsonb_build_object('check','candidate-T4-004-option-2','result',COALESCE(jsonb_agg(candidate_row),'[]'::jsonb)) FROM (SELECT t.product_category_name_english, ROUND(SUM(oi.price+oi.freight_value),2) AS sales FROM order_items oi JOIN orders o ON o.order_id=oi.order_id JOIN products p ON p.product_id=oi.product_id LEFT JOIN product_category_translation t ON t.product_category_name=p.product_category_name WHERE p.product_category_name IS NOT NULL AND o.order_status NOT IN ('canceled','unavailable') GROUP BY p.product_category_name,t.product_category_name_english ORDER BY sales DESC,p.product_category_name LIMIT 1) candidate_row;
SELECT jsonb_build_object('check','candidate-T4-006-option-1','result',COALESCE(jsonb_agg(candidate_row),'[]'::jsonb)) FROM (SELECT s.seller_state,ROUND(SUM(oi.price),2) AS sales FROM order_items oi JOIN sellers s ON s.seller_id=oi.seller_id GROUP BY s.seller_state ORDER BY sales DESC LIMIT 100) candidate_row;
SELECT jsonb_build_object('check','candidate-T4-006-option-2','result',COALESCE(jsonb_agg(candidate_row),'[]'::jsonb)) FROM (SELECT s.seller_state,ROUND(SUM(oi.price+oi.freight_value),2) AS sales FROM order_items oi JOIN orders o ON o.order_id=oi.order_id JOIN sellers s ON s.seller_id=oi.seller_id WHERE o.order_status NOT IN ('canceled','unavailable') GROUP BY s.seller_state ORDER BY sales DESC LIMIT 100) candidate_row;
SELECT jsonb_build_object('check','candidate-T4-013','result',COALESCE(jsonb_agg(candidate_row),'[]'::jsonb)) FROM (SELECT c.customer_state,COUNT(DISTINCT o.order_id) AS cnt FROM order_reviews r JOIN orders o ON o.order_id=r.order_id JOIN customers c ON c.customer_id=o.customer_id WHERE r.review_score IN (1,2) GROUP BY c.customer_state ORDER BY cnt DESC LIMIT 100) candidate_row;
SELECT jsonb_build_object('check','candidate-T4-015-option-1','result',COALESCE(jsonb_agg(candidate_row),'[]'::jsonb)) FROM (SELECT r.macro_region,COUNT(o.order_id) AS cnt FROM orders o LEFT JOIN customers c ON c.customer_id=o.customer_id LEFT JOIN regions r ON r.region_code=c.customer_state GROUP BY r.macro_region ORDER BY cnt DESC LIMIT 100) candidate_row;
SELECT jsonb_build_object('check','candidate-T4-019','result',COALESCE(jsonb_agg(candidate_row),'[]'::jsonb)) FROM (SELECT t.tag_id,COUNT(DISTINCT m.member_id) AS cnt FROM user_tags t LEFT JOIN user_tag_map tm ON tm.tag_id=t.tag_id LEFT JOIN members m ON m.member_id=tm.member_id GROUP BY t.tag_id ORDER BY cnt DESC,t.tag_id LIMIT 100) candidate_row;
SELECT jsonb_build_object('check','candidate-T4-024','result',COALESCE(jsonb_agg(candidate_row),'[]'::jsonb)) FROM (SELECT w.warehouse_name,COUNT(s.shipment_id) AS cnt FROM warehouses w FULL JOIN shipments s ON s.warehouse_id=w.warehouse_id GROUP BY w.warehouse_name ORDER BY cnt DESC LIMIT 100) candidate_row;
SELECT jsonb_build_object('check','candidate-T4-028','result',COALESCE(jsonb_agg(candidate_row),'[]'::jsonb)) FROM (SELECT COALESCE(st.category_id,tc.category_id) AS category_id,ROUND((AVG(EXTRACT(EPOCH FROM(st.resolved_at-st.created_at))/3600.0))::numeric,2) AS avg_hours FROM ticket_categories tc FULL JOIN support_tickets st ON st.category_id=tc.category_id GROUP BY COALESCE(st.category_id,tc.category_id) ORDER BY avg_hours DESC NULLS LAST LIMIT 100) candidate_row;
SELECT jsonb_build_object('check','candidate-T4-035','result',COALESCE(jsonb_agg(candidate_row),'[]'::jsonb)) FROM (WITH order_totals AS (SELECT order_id,SUM(price+freight_value) AS amount FROM order_items GROUP BY order_id),per_person AS (SELECT c.customer_unique_id,ROUND(SUM(t.amount)/NULLIF(COUNT(o.order_id),0),2) AS avg_order_value FROM orders o JOIN customers c ON c.customer_id=o.customer_id LEFT JOIN order_totals t ON t.order_id=o.order_id WHERE o.order_status NOT IN ('canceled','unavailable') GROUP BY c.customer_unique_id) SELECT customer_unique_id,avg_order_value FROM per_person WHERE avg_order_value IS NOT NULL ORDER BY avg_order_value DESC,customer_unique_id LIMIT 10) candidate_row;
SELECT jsonb_build_object('check','candidate-T4-039','result',COALESCE(jsonb_agg(candidate_row),'[]'::jsonb)) FROM (SELECT ROUND(COUNT(*) FILTER(WHERE clicked_product_id IS NOT NULL)::numeric/NULLIF(COUNT(*),0),4) AS ctr FROM search_logs) candidate_row;
SELECT jsonb_build_object('check','candidate-T4-044','result',COALESCE(jsonb_agg(candidate_row),'[]'::jsonb)) FROM (SELECT r.macro_region,COUNT(DISTINCT c.customer_id) AS customers,ROUND(COUNT(o.order_id)::numeric/NULLIF(COUNT(DISTINCT c.customer_unique_id),0),2) AS orders_per_customer FROM customers c LEFT JOIN regions r ON r.region_code=c.customer_state LEFT JOIN orders o ON o.customer_id=c.customer_id GROUP BY r.macro_region ORDER BY customers DESC LIMIT 100) candidate_row;
COMMIT;
